 	do_create = !io_wqe_activate_free_worker(wqe, acct);
 	rcu_read_unlock();

 	raw_spin_unlock(&wqe->lock);

 	if (do_create && ((work_flags & IO_WQ_WORK_CONCURRENT) ||
 	    !atomic_read(&acct->nr_running))) {
